// Run first. People who know at least one person, with their degree, most connected first.
query connected_people() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle
        $p.name
        count($f) as degree
    }
    order { degree desc }
}
```

```gq
// Run second. The caller appends these people to the first result with degree = 0, after all the connected rows.
query isolated_people() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}
